`); response.write(`data: ${JSON.stringify(payload)}

`); return true; } catch { return false; } }; // Catch-up: replay buffered events the client hasn't seen yet. const replayEvents = Array.isArray(job.events) ? job.events.filter(event => Number(event.seq) > afterSeq) : []; for (const event of replayEvents) { if (!writeFrame('event', event)) break; } // Initial status snapshot so the client immediately has full text + status. writeFrame('status', { status: job.status, text: job.text, last_seq: job.lastSeq, error: job.error |

